<template><WorkspaceLayout role="USER"><div class="heading"><div><p class="eyebrow">生活提醒</p><h1 class="page-title">把重要的小事记在心上。</h1><p class="muted">提醒会投递到当前有权账号的站内消息；网站离线时无法保证实时看到。</p></div><button class="primary" @click="createOpen=true">新建提醒</button></div><p v-if="error" class="error" role="alert">{{ error }}</p><div class="list"><article v-for="reminder in reminders" :key="reminder.id" class="surface reminder"><div><span class="eyebrow">{{ reminder.elder_name }} · {{ recurrenceName(reminder.recurrence) }}</span><h2>{{ reminder.title }}</h2><p class="muted">{{ reminder.status==='ACTIVE'?`下次提醒：${formatTime(reminder.next_fire_at)}`:reminder.status==='FINISHED'?'已结束':'已停止' }}</p></div><button v-if="reminder.status==='ACTIVE'" class="text-button" @click="stop(reminder.id)">停止提醒</button></article><div v-if="!reminders.length&&!error" class="empty">暂无生活提醒。</div></div><el-dialog v-model="createOpen" title="新建生活提醒" width="min(94vw, 540px)"><el-form label-position="top"><el-form-item label="服务对象"><el-select v-model="form.elderId" style="width:100%"><el-option v-for="elder in elders" :key="elder.id" :label="elder.fullName" :value="elder.id" /></el-select></el-form-item><el-form-item label="提醒内容"><el-input v-model="form.title" maxlength="100" /></el-form-item><el-form-item label="重复规则"><el-select v-model="form.recurrence" style="width:100%"><el-option label="单次" value="ONCE" /><el-option label="每日" value="DAILY" /><el-option label="每周" value="WEEKLY" /></el-select></el-form-item><el-form-item label="首次提醒时间"><el-input v-model="form.firstAt" type="datetime-local" /></el-form-item></el-form><template #footer><button class="primary" @click="create">保存提醒</button></template></el-dialog></WorkspaceLayout></template>
<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import WorkspaceLayout from '../../layouts/WorkspaceLayout.vue'
import { api } from '../../api/client'
type Reminder={id:number;elder_name:string;title:string;recurrence:string;next_fire_at:string|null;status:string}
type Elder={id:number;fullName:string}
const reminders=ref<Reminder[]>([]),elders=ref<Elder[]>([]),error=ref(''),createOpen=ref(false)
const form=reactive({elderId:undefined as number|undefined,title:'',recurrence:'ONCE',firstAt:''})
function recurrenceName(value:string){return ({ONCE:'单次',DAILY:'每日',WEEKLY:'每周'} as Record<string,string>)[value]||value}
function formatTime(value:string|null){return value?new Date(value).toLocaleString('zh-CN',{hour12:false}):'—'}
async function load(){try{[reminders.value,elders.value]=await Promise.all([api<Reminder[]>('/reminders'),api<Elder[]>('/elders')]);error.value=''}catch(reason){error.value=reason instanceof Error?reason.message:'加载失败'}}
async function create(){if(!form.elderId||!form.title.trim()||!form.firstAt){ElMessage.error('请完整填写提醒信息');return}try{await api('/reminders',{method:'POST',body:JSON.stringify(form)});createOpen.value=false;await load();ElMessage.success('提醒已创建')}catch(reason){ElMessage.error(reason instanceof Error?reason.message:'创建失败')}}
async function stop(id:number){try{await ElMessageBox.confirm('确认停止这条提醒？','请确认');await api(`/reminders/${id}/stop`,{method:'POST'});await load();ElMessage.success('提醒已停止')}catch(reason){if(reason instanceof Error)ElMessage.error(reason.message)}}
onMounted(load)
</script>
<style scoped>.heading{display:flex;justify-content:space-between;align-items:center;gap:20px}.heading .muted{max-width:700px}.list{display:grid;gap:15px;margin-top:30px}.reminder{display:flex;justify-content:space-between;align-items:center;padding:26px;gap:18px}.reminder h2{margin:8px 0}.error{color:#b34939}@media(max-width:650px){.heading,.reminder{align-items:flex-start;flex-direction:column}}</style>
